// ==========================================
// GENERATE RUN ID + NORMALIZE CONFIGURATION
// ==========================================

const input = $json;


// ==========================================
// READ POSSIBLE DATA SOURCES
// ==========================================

// Support both:
// 1. Flattened fields
// 2. Nested fields

const body = input.body || {};

const selection = input.selection || body.selection || {};
const message = input.message || body.message || {};
const attachments = input.attachments || body.attachments || {};


// ==========================================
// POSITIONS
// ==========================================

let positions =
  input.positions ??
  body.positions ??
  [];

if (!Array.isArray(positions)) {
  positions = [positions].filter(Boolean);
}


// ==========================================
// SELECTION MODE
// ==========================================

let selectedRows =
  input.selected_rows ??
  selection.rows ??
  body.selected_rows ??
  [];

if (!Array.isArray(selectedRows)) {
  selectedRows = [];
}


// If rows are selected → rows mode
// Otherwise → positions mode

let selectionMode =
  input.selection_mode ??
  selection.mode ??
  body.selection_mode ??
  "";

selectionMode = String(selectionMode).trim();

if (!selectionMode) {
  selectionMode =
    selectedRows.length > 0
      ? "rows"
      : positions.length > 0
        ? "positions"
        : "rows";
}


// ==========================================
// MESSAGE SUBJECT
// ==========================================

let subject =
  input.subject ??
  input.message_subject ??
  message.subject ??
  body.subject ??
  body.message_subject ??
  "";

subject = String(subject).trim();


// ==========================================
// MESSAGE BODY
// ==========================================

let messageBody =
  input.message_body ??
  input.messageBody ??
  message.body ??
  body.message_body ??
  body.messageBody ??
  "";

messageBody = String(messageBody).trim();


// ==========================================
// CHECK TEXT
// ==========================================

let checkText =
  input.check_text ??
  body.check_text ??
  "";

checkText = String(checkText).trim();


// ==========================================
// SAFE FALLBACK FOR SUBJECT
// ==========================================

// If Admin did not provide a separate subject,
// use check_text as the subject.

if (!subject && checkText) {
  subject = checkText;
}


// ==========================================
// SAFE FALLBACK FOR MESSAGE BODY
// ==========================================

// If Admin did not provide message body,
// use a basic configured template.

if (!messageBody) {
  messageBody =
`Hello {{name}},

I am interested in the {{position}} opportunity.

Best regards`;
}


// ==========================================
// ATTACHMENTS
// ==========================================

let attachmentMode =
  input.attachment_mode ??
  attachments.mode ??
  body.attachment_mode ??
  "";

attachmentMode = String(attachmentMode).trim();


// If no attachment mode is provided,
// default to none.

if (!attachmentMode) {
  attachmentMode = "none";
}


let attachmentFileIds =
  input.attachment_file_ids ??
  attachments.file_ids ??
  body.attachment_file_ids ??
  [];

if (!Array.isArray(attachmentFileIds)) {
  attachmentFileIds = [];
}


// ==========================================
// FILES PER EMAIL
// ==========================================

let filesPerEmail =
  input.files_per_email ??
  attachments.files_per_email ??
  body.files_per_email ??
  1;

filesPerEmail = Number(filesPerEmail);

if (!Number.isFinite(filesPerEmail) || filesPerEmail < 1) {
  filesPerEmail = 1;
}


// ==========================================
// LIMITS
// ==========================================

let maxPerRun = Number(
  input.max_per_run ??
  body.max_per_run ??
  50
);

if (!Number.isFinite(maxPerRun) || maxPerRun < 1) {
  maxPerRun = 50;
}


let maxPerDay = Number(
  input.max_per_day ??
  body.max_per_day ??
  100
);

if (!Number.isFinite(maxPerDay) || maxPerDay < 1) {
  maxPerDay = 100;
}


// ==========================================
// DELAY
// ==========================================

let delayMin = Number(
  input.delay_min ??
  body.delay_min ??
  30
);

if (!Number.isFinite(delayMin) || delayMin < 0) {
  delayMin = 30;
}


let delayMax = Number(
  input.delay_max ??
  body.delay_max ??
  90
);

if (!Number.isFinite(delayMax) || delayMax < delayMin) {
  delayMax = 90;
}


// ==========================================
// BOOLEAN VALUES
// ==========================================

const strictMode =
  input.strict_mode === true ||
  input.strict_mode === "true";

const dryRun =
  input.dry_run === true ||
  input.dry_run === "true";

const requireAdminApproval =
  input.require_admin_approval === true ||
  input.require_admin_approval === "true";


// ==========================================
// GENERATE RUN ID
// ==========================================

const run_id = `RUN-${$execution.id}`;


// ==========================================
// VALIDATION
// ==========================================

const errors = [];


// Position
if (positions.length === 0) {
  errors.push("Position missing");
}


// Selection
if (
  !["rows", "positions", "all"].includes(selectionMode)
) {
  errors.push(
    `Invalid selection_mode: "${selectionMode}"`
  );
}


// Rows only required when rows mode
if (
  selectionMode === "rows" &&
  selectedRows.length === 0
) {
  errors.push("Selected rows missing");
}


// Subject
if (!subject) {
  errors.push("Message subject is missing");
}


// Message body
if (!messageBody) {
  errors.push("Message body is missing");
}


// Attachment mode
if (
  !["none", "specific", "shuffle"].includes(
    attachmentMode
  )
) {
  errors.push(
    `Invalid attachment_mode: "${attachmentMode}"`
  );
}


// Specific attachment
if (
  attachmentMode === "specific" &&
  attachmentFileIds.length === 0
) {
  errors.push("Attachment file is missing");
}


// Files per email
if (filesPerEmail < 1) {
  errors.push(
    `Invalid files_per_email: "${filesPerEmail}"`
  );
}


// Limits
if (maxPerRun < 1) {
  errors.push("Invalid max_per_run");
}

if (maxPerDay < 1) {
  errors.push("Invalid max_per_day");
}


// Delay
if (delayMin < 0) {
  errors.push("Invalid delay_min");
}

if (delayMax < delayMin) {
  errors.push(
    "delay_max must be greater than or equal to delay_min"
  );
}


// ==========================================
// CONFIG VALID
// ==========================================

const config_valid = errors.length === 0;


// ==========================================
// OUTPUT
// ==========================================

return [
  {
    json: {
      ...input,

      // Run
      run_id,

      // Selection
      positions,
      selection_mode: selectionMode,
      selected_rows: selectedRows,

      // Message
      subject,
      message_body: messageBody,
      check_text: checkText,

      // Attachments
      attachment_mode: attachmentMode,
      attachment_file_ids: attachmentFileIds,
      files_per_email: filesPerEmail,

      // Settings
      strict_mode: strictMode,
      dry_run: dryRun,
      require_admin_approval: requireAdminApproval,

      // Limits
      max_per_run: maxPerRun,
      max_per_day: maxPerDay,

      // Delay
      delay_min: delayMin,
      delay_max: delayMax,

      // Validation
      config_valid,
      validation_errors: errors
    }
  }
];

const run_id = $('Init Run Log').first().json.run_id;
const items = $input.all();

if (
  !items.length ||
  (items.length === 1 && Object.keys(items[0].json).length === 0)
) {
  return [{ json: { _empty: true } }];
}

return items.map(i => {
  const data = i.json;

  // Support both lowercase and original Google Sheet headers
  const name = String(
    data.name ??
    data.Name ??
    data['Full Name'] ??
    ''
  ).trim();

  const email = String(
    data.email ??
    data.Email ??
    data['Email Address'] ??
    ''
  ).trim().toLowerCase();

  const company = String(
    data.company ??
    data.Company ??
    data['Company Name'] ??
    data['Company Name '] ??
    ''
  ).trim();

  const category = String(
    data.category ??
    data.Category ??
    data['Contact Category'] ??
    data['Contact Type'] ??
    ''
  ).trim();

  return {
    json: {
      row_number: data.row_number,
      name,
      email,
      company,
      category,
      run_id
    }
  };
});

const sent = new Set($input.all()
  .filter(i => String(i.json.Status || '').toLowerCase() === 'sent')
  .map(i => String(i.json.Email || '').toLowerCase()));
return $('Remove Duplicate Emails').all().map(i => ({
  json: { ...i.json, already_sent: sent.has(i.json.email) } }));

return $input.all().map(item => {
  const data = item.json;

  // Possible category fields
  const rawCategory = String(
    data.category ??
    data.Category ??
    data.contact_type ??
    data.ContactType ??
    data.type ??
    data.Type ??
    data.status ??
    ""
  ).trim();

  const categoryLower = rawCategory.toLowerCase();

  let category_norm = "Other";

  // Lead first
  if (
    categoryLower.includes("lead") ||
    categoryLower.includes("prospect") ||
    categoryLower.includes("potential")
  ) {
    category_norm = "Lead";
  }

  // Client
  else if (
    categoryLower.includes("client") ||
    categoryLower.includes("customer") ||
    categoryLower.includes("buyer")
  ) {
    category_norm = "Client";
  }

  return {
    json: {
      ...data,

      // Debug fields
      original_category: rawCategory,
      category_norm: category_norm
    }
  };
});

const items = $input.all().map(i => i.json);
const by = {};
items.forEach(i => by[i.category_norm] = (by[i.category_norm] || 0) + 1);
const rows = items.slice(0, 25).map(i => `<tr><td>${i.name}</td><td>${i.email}</td><td>${i.category_norm}</td></tr>`).join('');
const summary = Object.entries(by).map(([k, v]) => `${k}: ${v}`).join(' | ');
const run_id = $('Init Run Log').first().json.run_id;
const html = `<h3>Dry run ${run_id}</h3><p>${items.length} emails ready to send.</p><p>${summary}</p><table border="1" cellpadding="4"><tr><th>Name</th><th>Email</th><th>Category</th></tr>${rows}</table><p>Showing first 25 recipients. Nothing has been sent yet.</p>`;
return [{ json: { run_id, total: items.length, summary, report_html: html } }];

const rows = $('Append Send Log').all().map(i => i.json);
const sent = rows.filter(r => r.Status === 'Sent').length;
const failed = rows.filter(r => r.Status === 'Failed');
const run_id = $('Init Run Log').first().json.run_id;
const failList = failed.map(r => `<li>${r.Email}: ${r.Error}</li>`).join('');
const html = `<h3>Run ${run_id} complete</h3><p>Sent: ${sent}<br>Failed: ${failed.length}<br>Total processed: ${rows.length}</p>${failed.length ? '<p>Failures:</p><ul>' + failList + '</ul>' : ''}`;
return [{ json: { run_id, sent, failed: failed.length, total: rows.length, report_html: html } }];

// ==========================================
// VALIDATE CONFIGURATION (fixed)
// ==========================================

const input = $json;

// Default CV file ID (Google Drive). Used when attachment_file_ids is not received.
const DEFAULT_ATTACHMENT_FILE_ID = "1lWTGBIMYhklwgiCRNS6AMQCDeW4HxNw3";

// Helper: first non-empty value among several possible field names
const pick = (...keys) => {
  for (const k of keys) {
    const v = input[k];
    if (v !== undefined && v !== null && String(v).trim() !== "") return v;
  }
  return "";
};

// ==========================================
// SPREADSHEET ID (accepts full URL too)
// ==========================================

let spreadsheetId = String(
  pick("spreadsheetId", "spreadsheet_id", "sheet_id", "sheetId")
).trim();

const urlMatch = spreadsheetId.match(/\/d\/([a-zA-Z0-9_-]+)/);
if (urlMatch) spreadsheetId = urlMatch[1];

// ==========================================
// POSITIONS
// ==========================================

const rawPositions = pick("positions", "position");
const positions = Array.isArray(rawPositions)
  ? rawPositions.filter(Boolean)
  : String(rawPositions)
      .split(",")
      .map(p => p.trim())
      .filter(Boolean);

// ==========================================
// SELECTED ROWS
// ==========================================

const selectedRows = Array.isArray(input.selected_rows)
  ? input.selected_rows
  : [];

// ==========================================
// SELECTION MODE
// ==========================================

let selectionMode = String(input.selection_mode || "").trim().toLowerCase();

if (!selectionMode) {
  if (selectedRows.length > 0) selectionMode = "rows";
  else if (positions.length > 0) selectionMode = "positions";
  else selectionMode = "all";
}

// ==========================================
// SUBJECT / BODY / CHECK TEXT
// ==========================================

const subject = String(
  pick("subject", "emailSubject", "email_subject")
).trim();

const messageBody = String(
  pick("message_body", "messageBody", "emailBody", "email_body")
).trim();

const checkText = String(
  pick("check_text", "checkText")
).trim();

// ==========================================
// ATTACHMENTS
// ==========================================

const attachmentMode = String(
  input.attachment_mode || "none"
).trim().toLowerCase();

const rawAttachmentIds = pick(
  "attachment_file_ids",
  "attachment_file_id",
  "attachmentFileIds",
  "attachmentFileId",
  "attachment_ids",
  "file_ids",
  "file_id"
);

let attachmentFileIds = (
  Array.isArray(rawAttachmentIds)
    ? rawAttachmentIds
    : String(rawAttachmentIds).split(/[,\n;]+/)
)
  .map(s => String(s).trim())
  .filter(Boolean);

// Fallback: if mode is "specific" but no ID arrived, use the default CV
if (attachmentMode === "specific" && attachmentFileIds.length === 0) {
  attachmentFileIds = [DEFAULT_ATTACHMENT_FILE_ID];
}

// ==========================================
// NUMBERS (empty string -> default)
// ==========================================

const num = (value, fallback) => {
  if (value === "" || value === null || value === undefined) return fallback;
  const n = Number(value);
  return Number.isFinite(n) ? n : fallback;
};

const filesPerEmail = num(input.files_per_email, 1);
const maxPerRun     = num(input.max_per_run, 50);
const maxPerDay     = num(input.max_per_day, 100);
const delayMin      = num(input.delay_min, 30);
const delayMax      = num(input.delay_max, 90);

// ==========================================
// VALIDATION
// ==========================================

const errors = [];

if (!spreadsheetId) {
  errors.push("spreadsheetId missing");
}

if (!["rows", "positions", "all"].includes(selectionMode)) {
  errors.push(`Invalid selection_mode: "${selectionMode}"`);
}

// Positions are required ONLY when mode = positions
if (selectionMode === "positions" && positions.length === 0) {
  errors.push("Position missing");
}

// Rows are required ONLY when mode = rows
if (selectionMode === "rows" && selectedRows.length === 0) {
  errors.push("Selected rows missing. Either select rows or use selection_mode = positions.");
}

if (!subject) errors.push("Subject missing");
if (!messageBody) errors.push("Message body missing");
if (!checkText) errors.push("Check text missing");

if (!["none", "specific", "shuffle"].includes(attachmentMode)) {
  errors.push(`Invalid attachment_mode: "${attachmentMode}"`);
}

if (attachmentMode === "specific" && attachmentFileIds.length === 0) {
  errors.push("Attachment file missing");
}

if (filesPerEmail < 1) errors.push("files_per_email must be at least 1");
if (maxPerRun < 1)     errors.push("max_per_run must be at least 1");
if (maxPerDay < 1)     errors.push("max_per_day must be at least 1");
if (delayMin < 0)      errors.push("delay_min cannot be negative");
if (delayMax < delayMin) errors.push("delay_max must be greater than or equal to delay_min");

const config_valid = errors.length === 0;

// ==========================================
// OUTPUT
// ==========================================

return [
  {
    json: {
      ...input,

      run_id: input.run_id || `RUN-${$execution.id}`,

      spreadsheetId,
      positions,
      selection_mode: selectionMode,
      selected_rows: selectedRows,

      subject,
      message_body: messageBody,
      check_text: checkText,

      attachment_mode: attachmentMode,
      attachment_file_ids: attachmentFileIds,
      files_per_email: filesPerEmail,

      max_per_run: maxPerRun,
      max_per_day: maxPerDay,
      delay_min: delayMin,
      delay_max: delayMax,

      config_valid,
      validation_errors: errors,

      // Debug: what the Code node actually received
      debug_received_keys: Object.keys(input),
      debug_attachment_raw: rawAttachmentIds
    }
  }
];
